   where p.code = nc.code
     and p.cost is distinct from nc.cost
  returning p.id
),
upd_sales as (
  update public.sales s
     set unit_cost = nc.cost
    from new_cost nc
    join public.products p on p.code = nc.code
   where s.product_id = p.id
     and s.sold_at >= '2026-09-01'
  returning s.id
)
select (select count(*) from upd_products) as 상품_원가변경건수,
       (select count(*) from upd_sales)    as 판매건_9월이후_반영건수;
